/**
 * Text utility functions to ensure consistent text processing
 * throughout the animation system
 */

/**
 * Processes text to properly handle whitespace based on preferences
 * @param text The text to process
 * @param preserveWhitespace Whether to preserve whitespace
 * @returns Processed text
 */
export const processText = (text, preserveWhitespace) => {
  if (!text) return '';
  if (preserveWhitespace) {
    return text;
  } else {
    // Replace multiple spaces with a single space
    // and trim whitespace from the beginning and end
    return text.replace(/\s+/g, ' ').trim();
  }
};

/**
 * Truncates text at a natural breakpoint (word boundary) to avoid
 * cutting words in the middle
 * @param text The text to truncate
 * @param maxLength Maximum length of the truncated text
 * @param addEllipsis Whether to add an ellipsis at the end
 * @returns Truncated text
 */
export const truncateAtWordBoundary = (text, maxLength, addEllipsis = true) => {
  if (!text || text.length <= maxLength) {
    return text;
  }

  // Find the last space before the maxLength
  const lastSpace = text.lastIndexOf(' ', maxLength);

  // If no space found, truncate at maxLength
  const truncationPoint = lastSpace > 0 ? lastSpace : maxLength;

  // Truncate at the determined point
  let truncated = text.substring(0, truncationPoint).trim();

  // Add ellipsis if needed
  if (addEllipsis && text.length > truncationPoint) {
    truncated += '...';
  }
  return truncated;
};

